const webhookItem = $("MAIN 01 — Dashboard Webhook Trigger").item.json;
const body = webhookItem.body || webhookItem;
const userId = String(body.userId || "").trim();
const projectId = body.projectId ? String(body.projectId).trim() : null;
const requestId = String(body.requestId || ("req-dash-" + Date.now()));
const backendUrl = String(body.backendUrl || "http://localhost:5000").replace(/\/+$/, "");
const internalSecret = String(body.internalSecret || "ai_jira_agent_internal_secret_2026");

const verifyRes = $("MAIN 03 — Project Access Verification").item.json || {};
const verifiedProject = verifyRes.project || verifyRes.data?.project || null;

const summaryRes = $("MAIN 04 — Fetch Dashboard Summary").item.json || {};
const statusRes = $("MAIN 05 — Fetch Status Distribution").item.json || {};
const breakdownRes = $("MAIN 06 — Fetch Issue Type Breakdown").item.json || {};
const trendRes = $("MAIN 07 — Fetch Issue Creation Trend").item.json || {};

const summary = summaryRes.data || summaryRes || {};
const status = statusRes.data || statusRes || {};
const breakdown = breakdownRes.data || breakdownRes || {};
const trend = trendRes.data || trendRes || {};

const totalIssues = summary.totalIssues !== undefined ? summary.totalIssues : (status.total || 0);
const doneIssues = status.done !== undefined ? status.done : (summary.statusDistribution?.done || 0);
const inProgressIssues = status.inProgress !== undefined ? status.inProgress : (summary.statusDistribution?.inProgress || 0);
const toDoIssues = status.toDo !== undefined ? status.toDo : (summary.statusDistribution?.toDo || 0);

// Tính tỷ lệ hoàn thành chính xác tuyệt đối, tránh lỗi chia cho 0
const rawRate = totalIssues > 0 ? (doneIssues / totalIssues) * 100 : 0;
const completionRate = parseFloat(rawRate.toFixed(1));

// Thống kê Story Points theo tiêu chuẩn Agile ước tính
const totalStoryPoints = summary.totalStoryPoints || ((summary.totalStories || 0) * 5 + (summary.totalTasks || 0) * 2);
const completedStoryPoints = Math.round((totalStoryPoints * completionRate) / 100);

const completionMetrics = {
  totalIssues,
  doneIssues,
  inProgressIssues,
  toDoIssues,
  completionRate,
  formattedPercentage: `${completionRate}%`,
  totalStoryPoints,
  completedStoryPoints,
  formula: "(Số issue Done ÷ Tổng số issue) × 100%",
  isZeroState: totalIssues === 0,
  calculatedAt: new Date().toISOString()
};

return [{
  json: {
    userId,
    projectId,
    requestId,
    backendUrl,
    internalSecret,
    verifiedProject,
    accessVerified: true,
    summary,
    status,
    breakdown,
    trend,
    datasetValid: true,
    completionMetrics,
    stage: "METRICS_CALCULATED"
  }
}];

const item = $input.first().json;
const { summary, status, breakdown, trend, completionMetrics, verifiedProject, requestId } = item;

// 1. Chuẩn hóa Status Distribution với mã màu và nhãn tiếng Việt phục vụ Pie/Donut Chart
const normalizedDistribution = [
  {
    status: "To Do",
    label: "Cần làm (To Do)",
    count: completionMetrics.toDoIssues,
    percentage: completionMetrics.totalIssues > 0 ? parseFloat(((completionMetrics.toDoIssues / completionMetrics.totalIssues) * 100).toFixed(1)) : 0,
    color: "#64748b"
  },
  {
    status: "In Progress",
    label: "Đang thực hiện (In Progress)",
    count: completionMetrics.inProgressIssues,
    percentage: completionMetrics.totalIssues > 0 ? parseFloat(((completionMetrics.inProgressIssues / completionMetrics.totalIssues) * 100).toFixed(1)) : 0,
    color: "#3b82f6"
  },
  {
    status: "Done",
    label: "Hoàn thành (Done)",
    count: completionMetrics.doneIssues,
    percentage: completionMetrics.totalIssues > 0 ? parseFloat(((completionMetrics.doneIssues / completionMetrics.totalIssues) * 100).toFixed(1)) : 0,
    color: "#10b981"
  }
];

// 2. Chuẩn hóa Summary DTO
const normalizedSummary = {
  totalProjects: summary.totalProjects || 0,
  totalEpics: summary.totalEpics || 0,
  totalStories: summary.totalStories || 0,
  totalTasks: summary.totalTasks || 0,
  totalIssues: completionMetrics.totalIssues,
  totalStoryPoints: completionMetrics.totalStoryPoints,
  issuesThisMonth: summary.issuesThisMonth || 0,
  epicsThisMonth: summary.epicsThisMonth || 0,
  storiesThisMonth: summary.storiesThisMonth || 0,
  tasksThisMonth: summary.tasksThisMonth || 0,
  completionRate: completionMetrics.completionRate,
  statusDistribution: {
    toDo: completionMetrics.toDoIssues,
    inProgress: completionMetrics.inProgressIssues,
    done: completionMetrics.doneIssues
  },
  timeWindow: summary.timeWindow || {
    monthStart: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString(),
    nextMonthStart: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 1).toISOString(),
    timezone: "UTC"
  },
  filteredProject: verifiedProject || summary.filteredProject || null
};

// 3. Chuẩn hóa Status DTO
const normalizedStatus = {
  total: completionMetrics.totalIssues,
  done: completionMetrics.doneIssues,
  inProgress: completionMetrics.inProgressIssues,
  toDo: completionMetrics.toDoIssues,
  completionRate: completionMetrics.completionRate,
  denominatorNote: "Mẫu số tính tỷ lệ hoàn thành là tổng số Issue trong phạm vi truy cập (To Do + In Progress + Done)",
  distribution: normalizedDistribution
};

// 4. Chuẩn hóa Breakdown DTO phục vụ BarChart
const normalizedBreakdown = breakdown.breakdown ? breakdown : {
  breakdown: [
    { type: "Epic", name: "Epics", thisMonth: summary.epicsThisMonth || 0, allTime: summary.totalEpics || 0 },
    { type: "Story", name: "Stories", thisMonth: summary.storiesThisMonth || 0, allTime: summary.totalStories || 0 },
    { type: "Task", name: "Tasks / Sub-tasks", thisMonth: summary.tasksThisMonth || 0, allTime: summary.totalTasks || 0 }
  ],
  totals: breakdown.totals || {
    thisMonth: (summary.epicsThisMonth || 0) + (summary.storiesThisMonth || 0) + (summary.tasksThisMonth || 0),
    allTime: (summary.totalEpics || 0) + (summary.totalStories || 0) + (summary.totalTasks || 0)
  }
};

// 5. Chuẩn hóa Creation Trend DTO phục vụ AreaChart/LineChart
const normalizedTrend = trend.trend ? trend : {
  month: new Date().toISOString().slice(0, 7),
  totalInMonth: summary.issuesThisMonth || 0,
  trend: []
};

return [{
  json: {
    ...item,
    normalizedSummary,
    normalizedStatus,
    normalizedBreakdown,
    normalizedTrend,
    stage: "RESULTS_NORMALIZED"
  }
}];

const item = $input.first().json || {};
let webhookBody = {};
try {
  const webhookItem = $("MAIN 01 — Dashboard Webhook Trigger").item.json || {};
  webhookBody = webhookItem.body || webhookItem;
} catch (e) {}

const requestId = item.requestId || webhookBody.requestId || ("req-dash-" + Date.now());
const now = new Date().toISOString();

// 1. Phân loại Access Denied (từ AUX 03 IF False)
const isAccessDenied = item.allowed === false || item.statusCode === 403 || item.error === "ACCESS_DENIED" || item.data?.allowed === false;
if (isAccessDenied) {
  const errRes = {
    success: false,
    statusCode: 403,
    errorCode: "PROJECT_ACCESS_DENIED",
    message: "Dự án không tồn tại hoặc người dùng không có quyền truy cập vào Workspace này.",
    requestId,
    timestamp: now
  };
  return [{ json: errRes }];
}

// 2. Phân loại Validation Error (từ MAIN 02 False)
const isValidationError = !webhookBody.userId || String(webhookBody.userId).trim().length === 0;
if (isValidationError) {
  const errRes = {
    success: false,
    statusCode: 400,
    errorCode: "INVALID_DASHBOARD_REQUEST",
    message: "Yêu cầu phân tích Dashboard không hợp lệ: Thiếu userId hoặc thông tin phiên làm việc.",
    requestId,
    timestamp: now
  };
  return [{ json: errRes }];
}

// 3. Phân loại Dataset Error (từ MAIN 08 False)
const errRes = {
  success: false,
  statusCode: 502,
  errorCode: "INVALID_ANALYTICS_DATASET",
  message: "Dữ liệu phân tích nhận được từ Backend bị thiếu hoặc không hợp lệ.",
  details: ["Một hoặc nhiều tập dữ liệu thống kê từ Backend không hợp lệ hoặc rỗng."],
  requestId,
  timestamp: now
};
return [{ json: errRes }];
